window.BOOTH_SCRIPT = {"version":"recording_v1","lines":[{"id":"0004","text":"닭볶음탕을 끓이려고 감자와 당근을 썰었습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0005","text":"삶은 달걀 껍질을 까다가 손톱이 조금 아팠어요.","style":"보통","lang":"Korean","stage":1},{"id":"0006","text":"넓은 들판에 노란 유채꽃이 가득 피었습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0008","text":"의자에 앉아 잠깐 숨을 고르고 다시 걸었습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0017","text":"왜 그런지 오늘따라 시간이 빨리 갑니다.","style":"보통","lang":"Korean","stage":1},{"id":"0020","text":"훨씬 가벼운 가방으로 바꾸고 나니 편해요.","style":"보통","lang":"Korean","stage":1},{"id":"0024","text":"굳이 그렇게까지 서두를 필요는 없었어요.","style":"보통","lang":"Korean","stage":1},{"id":"0035","text":"곰곰이 생각해 보니 내가 잘못 알았네요.","style":"보통","lang":"Korean","stage":1},{"id":"0038","text":"택시를 타고 기차역까지 십 분 만에 갔어요.","style":"보통","lang":"Korean","stage":1},{"id":"0046","text":"여름 방학에는 할머니 댁에서 수박을 먹었어요.","style":"보통","lang":"Korean","stage":1},{"id":"0051","text":"빨랫줄에 널어 둔 이불이 뽀송하게 말랐어요.","style":"보통","lang":"Korean","stage":1},{"id":"0060","text":"궤도를 도는 인공위성이 밤하늘에 빛났어요.","style":"보통","lang":"Korean","stage":1},{"id":"0067","text":"읊조리듯 낮은 목소리로 시를 읽었습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0077","text":"부엌에서 보글보글 찌개 끓는 소리가 납니다.","style":"보통","lang":"Korean","stage":1},{"id":"0113","text":"얘기하다 보니 벌써 밤이 깊었습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0119","text":"어제 본 영화의 마지막 장면이 계속 떠올라요.","style":"보통","lang":"Korean","stage":1},{"id":"0137","text":"깊은 산속 옹달샘에 토끼가 물을 마시러 왔습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0138","text":"맞춤법이 헷갈려서 사전을 찾아봤어요.","style":"보통","lang":"Korean","stage":1},{"id":"0452","text":"넋을 놓고 창밖만 바라보고 있었습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0458","text":"외곬으로 한 우물만 판 끝에 꿈을 이뤘어요.","style":"보통","lang":"Korean","stage":1},{"id":"0460","text":"고양이가 앞발을 핥으며 햇볕을 쬐고 있어요.","style":"보통","lang":"Korean","stage":1},{"id":"0466","text":"긁힌 자국이 남지 않도록 조심해서 옮겨 주세요.","style":"보통","lang":"Korean","stage":1},{"id":"0471","text":"주말 아침, 느지막이 일어나 창문을 열었더니 밤새 내린 눈이 온 세상을 하얗게 덮고 있었어요.","style":"보통","lang":"Korean","stage":1},{"id":"0472","text":"회사 앞 작은 카페는 사장님이 직접 원두를 볶아서, 문을 열기 전부터 고소한 향이 골목까지 퍼집니다.","style":"보통","lang":"Korean","stage":1},{"id":"0473","text":"처음 자전거를 배우던 날, 아버지가 뒤에서 잡아 주는 줄 알고 한참을 달렸는데 사실은 이미 손을 놓고 계셨어요.","style":"보통","lang":"Korean","stage":1},{"id":"0474","text":"오래된 라디오를 고쳐 보려고 뚜껑을 열었다가, 안에서 할아버지가 남긴 쪽지를 발견했습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0476","text":"장마가 끝나자 매미 소리가 하루 종일 이어졌고, 아이들은 개울가에서 물장구를 쳤습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0477","text":"도서관 맨 안쪽 서가에는 아무도 빌려 가지 않은 듯한 낡은 책들이 조용히 꽂혀 있었어요.","style":"보통","lang":"Korean","stage":1},{"id":"0521","text":"이 게임은 혼자서 만든 첫 번째 작품이에요.","style":"보통","lang":"Korean","stage":1},{"id":"0524","text":"다음 업데이트에서는 협동 모드가 추가될 예정입니다.","style":"보통","lang":"Korean","stage":1},{"id":"0422","text":"손끝으로 느껴지는 짜릿한 손맛을 경험해 보세요.","style":"보통","lang":"Korean","stage":1},{"id":"0425","text":"음악에 맞춰 장애물을 피하는 리듬 액션 게임이에요.","style":"보통","lang":"Korean","stage":1},{"id":"0426","text":"모든 캐릭터는 저마다 다른 능력을 가지고 있습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0427","text":"블록을 쌓아 가장 높은 탑을 만들어 보세요.","style":"보통","lang":"Korean","stage":1},{"id":"0431","text":"주인공은 기억을 잃은 채 낯선 섬에서 눈을 뜹니다.","style":"보통","lang":"Korean","stage":1},{"id":"0273","text":"최대 네 명까지 함께 파티를 맺을 수 있어요.","style":"보통","lang":"Korean","stage":1},{"id":"0282","text":"랭킹 일 위부터 백 위까지 보상이 지급돼요.","style":"보통","lang":"Korean","stage":1},{"id":"0284","text":"확률은 약 영 점 오 퍼센트로 아주 낮아요.","style":"보통","lang":"Korean","stage":1},{"id":"0289","text":"스킬 쿨타임이 끝나면 아이콘이 반짝입니다.","style":"보통","lang":"Korean","stage":1},{"id":"0297","text":"마우스 왼쪽 버튼을 누르면 공격합니다.","style":"보통","lang":"Korean","stage":1},{"id":"0301","text":"배틀로얄 모드에서는 백 명이 동시에 겨뤄요.","style":"보통","lang":"Korean","stage":1},{"id":"0305","text":"시즌 패스를 구매하면 스킨 열 종을 받아요.","style":"보통","lang":"Korean","stage":1},{"id":"0315","text":"생존 시간은 초 단위로 순위표에 기록됩니다.","style":"보통","lang":"Korean","stage":1},{"id":"0326","text":"좋아요, 출발합시다!","style":"보통","lang":"Korean","stage":1},{"id":"0343","text":"흠, 뭔가 이상한데요.","style":"보통","lang":"Korean","stage":1},{"id":"0351","text":"지난주에 친구들과 함께 처음 이 게임을 해 봤는데, 생각보다 훨씬 재미있어서 밤늦게까지 계속하게 됐어요.","style":"보통","lang":"Korean","stage":1},{"id":"0353","text":"처음에는 조작이 조금 어렵게 느껴질 수 있지만, 몇 판만 해 보면 금방 손에 익을 거예요.","style":"보통","lang":"Korean","stage":1},{"id":"0354","text":"비가 그친 뒤 무지개가 뜨면, 평소에는 볼 수 없던 특별한 상인이 마을에 찾아옵니다.","style":"보통","lang":"Korean","stage":1},{"id":"0355","text":"모험을 떠나기 전에 체력 물약과 해독제를 넉넉하게 챙겨 두는 것을 잊지 마세요.","style":"보통","lang":"Korean","stage":1},{"id":"0357","text":"열심히 모은 재료로 무기를 강화하면, 겉모습도 바뀌고 새로운 기술도 쓸 수 있습니다.","style":"보통","lang":"Korean","stage":1},{"id":"0153","text":"친구와 함께라면 어떤 던전도 즐거워요.","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0156","text":"귀여운 펫과 함께 마을을 산책해 보세요.","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0157","text":"오늘의 미션을 깨고 반짝이는 보상을 받으세요!","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0159","text":"누가 더 빨리 결승선에 도착할까요?","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0163","text":"한 판만 더, 이번엔 꼭 일등 할 거예요!","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0165","text":"쉽고 빠르게, 누구나 바로 즐길 수 있어요.","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0166","text":"콤보를 이어 갈수록 점수가 쑥쑥 올라가요!","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0171","text":"손대면 톡 하고 터질 것만 같은 풍선을 지켜라!","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0180","text":"지금 메이플스토리 월드에서 플레이해 보세요!","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0487","text":"꽁꽁 언 호수 위에서 신나는 썰매 경주가 시작돼요!","style":"밝고 신나게","lang":"Korean","stage":1},{"id":"0181","text":"조용한 숲속에서 당신만의 이야기가 시작됩니다.","style":"차분하게","lang":"Korean","stage":1},{"id":"0182","text":"천천히 걸어도 괜찮아요, 길은 사라지지 않으니까요.","style":"차분하게","lang":"Korean","stage":1},{"id":"0184","text":"별이 쏟아지는 밤, 등불을 들고 길을 나섭니다.","style":"차분하게","lang":"Korean","stage":1},{"id":"0185","text":"잊혀진 마을에는 오래된 비밀이 잠들어 있어요.","style":"차분하게","lang":"Korean","stage":1},{"id":"0186","text":"한 걸음씩, 퍼즐 조각을 맞춰 나가세요.","style":"차분하게","lang":"Korean","stage":1},{"id":"0188","text":"따뜻한 차 한 잔과 함께 쉬어 가는 게임이에요.","style":"차분하게","lang":"Korean","stage":1},{"id":"0202","text":"이야기는 아주 작은 씨앗 하나에서 시작됐습니다.","style":"차분하게","lang":"Korean","stage":1},{"id":"0207","text":"시간을 되돌릴 수 있다면, 무엇을 바꾸고 싶나요?","style":"차분하게","lang":"Korean","stage":1},{"id":"0492","text":"강물은 천천히 흘러 바다에 닿아요.","style":"차분하게","lang":"Korean","stage":1},{"id":"0495","text":"조용히 흔들리는 촛불처럼, 마음도 차분해져요.","style":"차분하게","lang":"Korean","stage":1},{"id":"0211","text":"절대 건드리지 마세요, 풍선이 곧 터질지도 몰라요.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0220","text":"누군가 거짓말을 하고 있어요, 범인을 찾아내세요.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0230","text":"살금살금, 들키는 순간 게임은 끝나요.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0231","text":"안개 속에서 붉은 눈이 번뜩였습니다.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0233","text":"삼, 이, 일, 이제 도망칠 곳은 없어요.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0236","text":"누가 먼저 무너질까요, 끝까지 눈을 떼지 마세요.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0237","text":"철문 너머에서 쇠사슬 끌리는 소리가 들립니다.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0501","text":"지금 움직이면 안 돼요, 녀석이 보고 있습니다.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0502","text":"통신이 끊겼다, 이제 남은 건 우리뿐이다.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0505","text":"배터리가 얼마 남지 않았어요, 손전등을 아껴 쓰세요.","style":"긴장감 있게","lang":"Korean","stage":1},{"id":"0244","text":"검을 들어라, 마지막 전투가 시작된다.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0246","text":"흩어진 영웅들이 다시 하나로 모입니다.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0248","text":"별들의 전쟁, 그 서막이 오릅니다.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0251","text":"바다를 건너고 산을 넘어, 전설의 끝을 향해.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0262","text":"하늘섬의 수호자들이 마지막 결전을 준비합니다.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0264","text":"열두 개의 탑, 열두 명의 군주, 단 하나의 왕좌.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0265","text":"폭풍이 몰아치는 바다 위, 해적왕의 항해가 시작된다.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0513","text":"천년 제국의 마지막 황제가 칼을 뽑았습니다.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0514","text":"바다의 지배자, 거대한 크라켄이 모습을 드러낸다.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0517","text":"하늘과 땅이 맞닿는 곳에서 최후의 결전이 펼쳐집니다.","style":"웅장하게","lang":"Korean","stage":1},{"id":"0361","text":"Welcome to the village at the edge of the world.","style":"보통","lang":"English","stage":1},{"id":"0362","text":"A brand new adventure starts right now.","style":"보통","lang":"English","stage":1},{"id":"0363","text":"Team up with your friends and defeat the boss.","style":"보통","lang":"English","stage":1},{"id":"0364","text":"Collect every key to unlock the secret room.","style":"보통","lang":"English","stage":1},{"id":"0365","text":"The clock is ticking, so hurry up!","style":"보통","lang":"English","stage":1},{"id":"0366","text":"Play it today on MapleStory Worlds!","style":"보통","lang":"English","stage":1},{"id":"0367","text":"Jump over the gap and grab the golden coin.","style":"보통","lang":"English","stage":1},{"id":"0368","text":"Can you survive until the very last second?","style":"보통","lang":"English","stage":1},{"id":"0369","text":"Build your own little house and invite your friends.","style":"보통","lang":"English","stage":1},{"id":"0370","text":"Every choice you make changes the story.","style":"보통","lang":"English","stage":1},{"id":"0003","text":"골목 끝 빵집에서 갓 구운 식빵 냄새가 났어요.","style":"보통","lang":"Korean","stage":2},{"id":"0007","text":"값을 깎아 달라고 했더니 덤으로 귤을 주셨어요.","style":"보통","lang":"Korean","stage":2},{"id":"0010","text":"쌀쌀한 바람이 불어서 목도리를 둘렀습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0013","text":"떡볶이는 조금 맵게, 순대는 넉넉하게 주세요.","style":"보통","lang":"Korean","stage":2},{"id":"0021","text":"흙 묻은 운동화를 깨끗하게 빨았습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0023","text":"밟으면 바스락 소리가 나는 낙엽이 좋아요.","style":"보통","lang":"Korean","stage":2},{"id":"0026","text":"해돋이를 보려고 새벽 네 시에 일어났어요.","style":"보통","lang":"Korean","stage":2},{"id":"0033","text":"옷걸이에 걸린 셔츠가 바람에 흔들렸어요.","style":"보통","lang":"Korean","stage":2},{"id":"0034","text":"휴대폰 배터리가 금방 닳아서 충전했습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0036","text":"찜질방에서 식혜를 마시며 푹 쉬었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0040","text":"핫초코 위에 마시멜로를 듬뿍 올렸어요.","style":"보통","lang":"Korean","stage":2},{"id":"0041","text":"그는 묵묵히 자기 일을 끝까지 해냈습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0044","text":"봄비가 내리고 나면 새싹이 쑥쑥 자라요.","style":"보통","lang":"Korean","stage":2},{"id":"0048","text":"찬물에 세수를 하니 정신이 번쩍 들었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0052","text":"씩씩하게 인사하는 아이 덕분에 웃었습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0053","text":"짜장면과 짬뽕 중에 하나만 고르기 어려워요.","style":"보통","lang":"Korean","stage":2},{"id":"0056","text":"무늬가 독특한 찻잔을 시장에서 샀어요.","style":"보통","lang":"Korean","stage":2},{"id":"0058","text":"쥐 한 마리가 창고 구석으로 쏙 숨었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0063","text":"많은 사람이 광장에 모여 불꽃놀이를 봤습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0066","text":"핥아 먹던 아이스크림이 바닥에 떨어졌어요.","style":"보통","lang":"Korean","stage":2},{"id":"0070","text":"닮은 듯 다른 쌍둥이 형제가 손을 흔들었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0072","text":"굶주린 고양이에게 밥을 챙겨 주었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0076","text":"꽃잎이 바람에 흩날리는 모습이 예뻤어요.","style":"보통","lang":"Korean","stage":2},{"id":"0078","text":"밭에서 막 캔 고구마를 쪄 먹었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0084","text":"옆집 아저씨가 손수 만든 잼을 나눠 주셨어요.","style":"보통","lang":"Korean","stage":2},{"id":"0085","text":"부엌 창틀에 작은 허브 화분을 놓았습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0086","text":"꺾인 나뭇가지를 조심스럽게 세워 주었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0087","text":"묶어 둔 운동화 끈이 자꾸 풀립니다.","style":"보통","lang":"Korean","stage":2},{"id":"0089","text":"닦아도 닦아도 창문에 얼룩이 남아요.","style":"보통","lang":"Korean","stage":2},{"id":"0095","text":"찌그러진 깡통을 발로 톡 찼습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0096","text":"논두렁을 따라 개구리 울음소리가 이어졌어요.","style":"보통","lang":"Korean","stage":2},{"id":"0097","text":"물감을 섞으니 예쁜 보라색이 나왔습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0099","text":"엘리베이터가 고장 나서 계단으로 올라갔습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0102","text":"주말 시장에서 싱싱한 딸기를 한 상자 샀어요.","style":"보통","lang":"Korean","stage":2},{"id":"0108","text":"하품을 참느라 눈물이 찔끔 났어요.","style":"보통","lang":"Korean","stage":2},{"id":"0110","text":"여행 가방에 옷을 차곡차곡 개어 넣었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0111","text":"요리책을 보면서 처음으로 케이크를 구웠습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0120","text":"오이를 얇게 썰어서 냉국을 만들었습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0134","text":"심심할 때는 오래된 사진첩을 넘겨 봐요.","style":"보통","lang":"Korean","stage":2},{"id":"0142","text":"밭이랑 사이로 아이들이 뛰어다녔어요.","style":"보통","lang":"Korean","stage":2},{"id":"0146","text":"맏언니가 동생들 숙제를 봐 주었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0451","text":"세 사람이 똑같이 몫을 나누기로 했어요.","style":"보통","lang":"Korean","stage":2},{"id":"0464","text":"맑게 갠 하늘 아래 연을 높이 날렸어요.","style":"보통","lang":"Korean","stage":2},{"id":"0467","text":"붉게 물든 저녁노을이 마을을 감쌌어요.","style":"보통","lang":"Korean","stage":2},{"id":"0468","text":"묽은 반죽에 밀가루를 조금 더 넣었습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0421","text":"이번 게임은 레트로 감성의 픽셀 그래픽으로 만들었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0424","text":"귀여운 겉모습과 달리 꽤 어려운 게임입니다.","style":"보통","lang":"Korean","stage":2},{"id":"0434","text":"낚시로 잡은 물고기를 시장에 팔아 돈을 모아요.","style":"보통","lang":"Korean","stage":2},{"id":"0435","text":"유령의 집에서 숨은 그림을 모두 찾아내세요.","style":"보통","lang":"Korean","stage":2},{"id":"0437","text":"하늘에서 떨어지는 별똥별을 피해 끝까지 살아남으세요.","style":"보통","lang":"Korean","stage":2},{"id":"0271","text":"레벨 십을 달성하면 두 번째 직업을 고를 수 있어요.","style":"보통","lang":"Korean","stage":2},{"id":"0279","text":"제한 시간 육십 초, 최고 점수에 도전하세요.","style":"보통","lang":"Korean","stage":2},{"id":"0280","text":"스테이지는 모두 스물네 개가 준비되어 있어요.","style":"보통","lang":"Korean","stage":2},{"id":"0288","text":"인벤토리가 가득 차면 아이템을 정리해 주세요.","style":"보통","lang":"Korean","stage":2},{"id":"0291","text":"길드에 가입하면 매일 길드 포인트를 받을 수 있어요.","style":"보통","lang":"Korean","stage":2},{"id":"0293","text":"크리티컬 확률을 올려 주는 반지를 착용했습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0294","text":"튜토리얼을 마치면 바로 메인 퀘스트가 시작돼요.","style":"보통","lang":"Korean","stage":2},{"id":"0298","text":"닉네임은 두 글자에서 여덟 글자까지 정할 수 있어요.","style":"보통","lang":"Korean","stage":2},{"id":"0299","text":"업데이트 내용은 공식 홈페이지에서 확인하세요.","style":"보통","lang":"Korean","stage":2},{"id":"0304","text":"치트키 없이 클리어하면 업적이 열립니다.","style":"보통","lang":"Korean","stage":2},{"id":"0306","text":"매일 자정에 상점 목록이 새로 바뀝니다.","style":"보통","lang":"Korean","stage":2},{"id":"0310","text":"FPS 게임처럼 일인칭 시점으로 즐길 수도 있어요.","style":"보통","lang":"Korean","stage":2},{"id":"0311","text":"UI 크기는 설정에서 바꿀 수 있습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0313","text":"NPC에게 말을 걸어 힌트를 얻으세요.","style":"보통","lang":"Korean","stage":2},{"id":"0316","text":"이번 패치에서 밸런스가 크게 조정되었어요.","style":"보통","lang":"Korean","stage":2},{"id":"0321","text":"정말요?","style":"보통","lang":"Korean","stage":2},{"id":"0322","text":"이게 끝이라고요?","style":"보통","lang":"Korean","stage":2},{"id":"0323","text":"와, 대단해요!","style":"보통","lang":"Korean","stage":2},{"id":"0324","text":"잠깐만요, 기다려 주세요.","style":"보통","lang":"Korean","stage":2},{"id":"0325","text":"준비됐나요?","style":"보통","lang":"Korean","stage":2},{"id":"0328","text":"고마워요, 정말 큰 도움이 됐어요.","style":"보통","lang":"Korean","stage":2},{"id":"0332","text":"아, 이제야 알겠어요!","style":"보통","lang":"Korean","stage":2},{"id":"0339","text":"어머, 깜짝이야!","style":"보통","lang":"Korean","stage":2},{"id":"0348","text":"쉿, 조용히 해 주세요.","style":"보통","lang":"Korean","stage":2},{"id":"0352","text":"마을 광장에 있는 커다란 시계탑에 올라가면, 섬 전체가 한눈에 내려다보이고 숨겨진 길도 찾을 수 있습니다.","style":"보통","lang":"Korean","stage":2},{"id":"0151","text":"새로운 모험이 지금 막 시작됩니다!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0152","text":"버섯 마을에 오신 걸 환영해요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0154","text":"톡톡 터지는 풍선을 모두 모아 보세요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0155","text":"점프 한 번에 구름 위까지 올라가요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0158","text":"알록달록한 사탕 나라로 떠나 볼까요?","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0168","text":"우리 팀이 이기면 모두에게 선물이 쏟아져요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0169","text":"리듬에 맞춰 북을 두드려 보세요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0175","text":"주말 이벤트, 놓치면 후회해요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0176","text":"하나, 둘, 셋, 지금 바로 출발!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0177","text":"꼬마 용사들의 신나는 대모험이 펼쳐집니다.","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0481","text":"딩동, 새로운 친구가 마을에 도착했어요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0482","text":"꽃이 피는 봄 축제, 지금 광장에서 열려요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0483","text":"동글동글 귀여운 몬스터를 모아 도감을 채워 보세요.","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0484","text":"빙글빙글 회전목마 위에서 보물을 찾아라!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0486","text":"팡팡 터지는 불꽃 속에서 친구들과 춤을 춰요!","style":"밝고 신나게","lang":"Korean","stage":2},{"id":"0183","text":"작은 정원을 가꾸며 하루를 보내 보세요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0187","text":"바람의 소리에 귀를 기울이면 길이 보입니다.","style":"차분하게","lang":"Korean","stage":2},{"id":"0189","text":"서두르지 않아도 돼요, 모든 순간이 소중하니까요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0190","text":"고요한 호수 위로 달빛이 길을 열어 줍니다.","style":"차분하게","lang":"Korean","stage":2},{"id":"0191","text":"오래 기다려 온 편지가 드디어 도착했어요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0192","text":"기억의 조각을 모아 잃어버린 이름을 찾아 주세요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0193","text":"숨을 고르고, 다음 수를 천천히 생각해 보세요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0195","text":"당신의 선택이 이야기의 끝을 바꿉니다.","style":"차분하게","lang":"Korean","stage":2},{"id":"0198","text":"하루의 끝, 오늘 모은 별을 하늘에 띄워 보세요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0199","text":"마음이 복잡할 때 잠시 들러 쉬어 가세요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0493","text":"빈 화분에 씨앗을 심고, 내일을 기다려 보세요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0494","text":"하얀 눈길 위에 당신의 발자국만 남습니다.","style":"차분하게","lang":"Korean","stage":2},{"id":"0496","text":"별을 잇는 선 하나하나에 이야기가 담겨 있습니다.","style":"차분하게","lang":"Korean","stage":2},{"id":"0498","text":"창밖의 빗소리를 들으며 잠시 쉬어 가세요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0499","text":"길은 멀지만, 함께라서 외롭지 않아요.","style":"차분하게","lang":"Korean","stage":2},{"id":"0212","text":"어둠 속에서 무언가가 당신을 지켜보고 있습니다.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0213","text":"남은 시간은 단 십 초, 지금 선택하세요.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0214","text":"발소리를 죽이고, 그림자 속으로 숨으세요.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0215","text":"문이 닫히기 전에 반드시 빠져나가야 합니다.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0216","text":"한 번의 실수가 모든 것을 끝낼 수 있어요.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0217","text":"숨을 참으세요, 놈이 바로 앞에 있습니다.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0218","text":"바닥이 무너지기 시작했어요, 서두르세요!","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0219","text":"마지막 한 명만 살아남을 수 있습니다.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0221","text":"불이 꺼지면, 절대 뒤를 돌아보지 마세요.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0222","text":"심장 박동이 빨라질수록 위험은 가까워집니다.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0223","text":"폭탄의 선은 두 개, 하나만 자를 수 있어요.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0225","text":"좀비 떼가 성문을 두드리고 있습니다.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0228","text":"탈출구는 하나, 열쇠는 아직 찾지 못했어요.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0235","text":"지금 이 순간에도 시계는 멈추지 않아요.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0238","text":"한 발짝만 잘못 디뎌도 낭떠러지예요.","style":"긴장감 있게","lang":"Korean","stage":2},{"id":"0241","text":"오래된 전설이 지금, 다시 깨어납니다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0242","text":"대륙의 운명이 당신의 손에 달려 있습니다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0243","text":"수천 년 동안 잠들어 있던 용이 눈을 떴다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0245","text":"하늘을 가르는 번개와 함께 새로운 시대가 열립니다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0247","text":"끝없는 사막 너머, 황금의 도시가 기다린다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0249","text":"왕국을 지킬 마지막 기사, 그대의 이름을 새겨라.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0250","text":"거대한 성벽이 무너지고, 진실이 드러납니다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0252","text":"신들의 시대가 저물고 인간의 시대가 밝아 온다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0253","text":"천 명의 군대보다 강한 단 한 사람의 용기.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0255","text":"불꽃 속에서 다시 태어난 불사조의 노래.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0256","text":"운명에 맞서 싸울 준비가 되었는가?","style":"웅장하게","lang":"Korean","stage":2},{"id":"0261","text":"피와 강철로 새긴 맹세를 잊지 마라.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0267","text":"이 세계의 마지막 희망이 지금 깨어난다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0268","text":"승리의 깃발을 높이 들어 올려라!","style":"웅장하게","lang":"Korean","stage":2},{"id":"0516","text":"얼어붙은 북쪽 땅에서 고대의 군대가 깨어났다.","style":"웅장하게","lang":"Korean","stage":2},{"id":"0371","text":"Pop the balloons and chase the high score!","style":"밝고 신나게","lang":"English","stage":2},{"id":"0372","text":"Ready, set, go!","style":"밝고 신나게","lang":"English","stage":2},{"id":"0373","text":"Meet adorable pets and explore the island together.","style":"밝고 신나게","lang":"English","stage":2},{"id":"0374","text":"New skins, new maps, and twice the fun this weekend!","style":"밝고 신나게","lang":"English","stage":2},{"id":"0375","text":"Who will reach the finish line first?","style":"밝고 신나게","lang":"English","stage":2},{"id":"0376","text":"Simple to learn, impossible to put down.","style":"밝고 신나게","lang":"English","stage":2},{"id":"0377","text":"Join the party and dance to the beat!","style":"밝고 신나게","lang":"English","stage":2},{"id":"0378","text":"Log in today and get a special hat for free!","style":"밝고 신나게","lang":"English","stage":2},{"id":"0379","text":"One more round, I know I can win this time!","style":"밝고 신나게","lang":"English","stage":2},{"id":"0380","text":"Catch the falling acorns before they hit the ground.","style":"밝고 신나게","lang":"English","stage":2},{"id":"0381","text":"Take your time, the path will still be here tomorrow.","style":"차분하게","lang":"English","stage":2},{"id":"0382","text":"A quiet forest hides a story only you can find.","style":"차분하게","lang":"English","stage":2},{"id":"0383","text":"Light a lantern and walk beneath the falling stars.","style":"차분하게","lang":"English","stage":2},{"id":"0384","text":"Gather the pieces of a memory you thought was lost.","style":"차분하게","lang":"English","stage":2},{"id":"0385","text":"Rest for a while by the warm fireplace.","style":"차분하게","lang":"English","stage":2},{"id":"0001","text":"오늘은 날씨가 맑아서 창문을 활짝 열어 두었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0002","text":"아침마다 따뜻한 보리차를 한 잔씩 마십니다.","style":"보통","lang":"Korean","stage":3},{"id":"0009","text":"꿈속에서 하늘을 나는 고래를 보았어요.","style":"보통","lang":"Korean","stage":3},{"id":"0011","text":"짧은 편지였지만 마음이 따뜻해졌어요.","style":"보통","lang":"Korean","stage":3},{"id":"0012","text":"뻐꾸기시계가 정각마다 노래를 부릅니다.","style":"보통","lang":"Korean","stage":3},{"id":"0014","text":"외갓집 마당에는 오래된 감나무가 있었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0015","text":"회의가 길어져서 점심을 늦게 먹었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0016","text":"귀여운 강아지가 꼬리를 흔들며 달려왔어요.","style":"보통","lang":"Korean","stage":3},{"id":"0018","text":"웬일로 동생이 먼저 설거지를 했어요.","style":"보통","lang":"Korean","stage":3},{"id":"0019","text":"돼지 저금통이 동전으로 묵직해졌습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0022","text":"읽고 싶은 책이 책상 위에 쌓여 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0025","text":"같이 가자고 했는데 친구가 먼저 떠났습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0027","text":"좋아하는 노래가 나와서 볼륨을 높였습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0028","text":"싫다고 말하는 것도 용기가 필요해요.","style":"보통","lang":"Korean","stage":3},{"id":"0029","text":"설날에는 온 가족이 모여 떡국을 먹어요.","style":"보통","lang":"Korean","stage":3},{"id":"0030","text":"신라의 옛 수도였던 경주에 다녀왔습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0031","text":"국물이 끓어 넘치기 전에 불을 줄였어요.","style":"보통","lang":"Korean","stage":3},{"id":"0032","text":"맑은 시냇물 위로 햇살이 반짝였습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0037","text":"칠판에 적힌 숙제를 공책에 옮겨 적었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0039","text":"퍼즐 조각 하나가 소파 밑에 숨어 있었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0042","text":"늦잠을 자서 버스를 놓칠 뻔했어요.","style":"보통","lang":"Korean","stage":3},{"id":"0043","text":"물고기 떼가 은빛으로 반짝이며 지나갔습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0045","text":"숲속 오두막에서 장작 타는 소리가 들렸습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0047","text":"자전거 바퀴에 바람을 넣고 출발했습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0049","text":"까치가 아침부터 반가운 소식을 전하네요.","style":"보통","lang":"Korean","stage":3},{"id":"0050","text":"뜨개질로 만든 장갑을 선물로 받았습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0054","text":"의사 선생님이 푹 쉬라고 말씀하셨어요.","style":"보통","lang":"Korean","stage":3},{"id":"0055","text":"희망을 잃지 않으면 길은 다시 보입니다.","style":"보통","lang":"Korean","stage":3},{"id":"0057","text":"회색 구름 사이로 파란 하늘이 보였습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0059","text":"꽤 오래 기다렸지만 결국 표를 구했습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0061","text":"값진 경험이었으니 후회는 없습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0062","text":"앉은 자리에서 책 한 권을 다 읽었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0064","text":"여덟 개의 상자를 차곡차곡 쌓았어요.","style":"보통","lang":"Korean","stage":3},{"id":"0065","text":"외곬으로 한 가지만 파고드는 성격입니다.","style":"보통","lang":"Korean","stage":3},{"id":"0068","text":"잃어버린 열쇠를 화분 아래에서 찾았어요.","style":"보통","lang":"Korean","stage":3},{"id":"0069","text":"없는 시간을 쪼개서 운동을 하고 있습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0071","text":"젊은 화가는 매일 새벽에 그림을 그립니다.","style":"보통","lang":"Korean","stage":3},{"id":"0073","text":"얇은 종이로 학을 천 마리 접었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0074","text":"짧게 자른 머리가 생각보다 잘 어울려요.","style":"보통","lang":"Korean","stage":3},{"id":"0075","text":"맛있는 냄새에 이끌려 부엌으로 갔습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0079","text":"낮에는 덥고 밤에는 쌀쌀한 날씨입니다.","style":"보통","lang":"Korean","stage":3},{"id":"0080","text":"숯불 위에서 고기가 지글지글 익어 갔어요.","style":"보통","lang":"Korean","stage":3},{"id":"0081","text":"겉보기와 달리 속은 아주 부드러웠습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0082","text":"꽂아 둔 책갈피가 어디로 갔는지 모르겠어요.","style":"보통","lang":"Korean","stage":3},{"id":"0083","text":"덮개를 덮어 두지 않으면 먼지가 쌓입니다.","style":"보통","lang":"Korean","stage":3},{"id":"0088","text":"섞어 놓은 카드를 한 장씩 뒤집어 보세요.","style":"보통","lang":"Korean","stage":3},{"id":"0090","text":"볶음밥 위에 달걀부침을 하나 올렸습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0091","text":"따뜻한 이불 속에서 나오기가 싫어요.","style":"보통","lang":"Korean","stage":3},{"id":"0092","text":"똑같은 실수를 두 번은 하지 않을 거예요.","style":"보통","lang":"Korean","stage":3},{"id":"0093","text":"뿌리 깊은 나무는 바람에 흔들리지 않습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0094","text":"쓸쓸한 가을밤에 귀뚜라미가 울었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0098","text":"손뼉을 치며 박자에 맞춰 노래했어요.","style":"보통","lang":"Korean","stage":3},{"id":"0100","text":"빗방울이 우산 위로 톡톡 떨어졌어요.","style":"보통","lang":"Korean","stage":3},{"id":"0101","text":"창밖으로 지나가는 기차를 한참 바라봤습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0103","text":"조용한 도서관에서 연필 소리만 들렸습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0104","text":"첫눈이 오면 꼭 연락하자고 약속했어요.","style":"보통","lang":"Korean","stage":3},{"id":"0105","text":"키보드 소리가 사무실에 가득 울렸습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0106","text":"토요일 오후에는 늘 산책을 나가요.","style":"보통","lang":"Korean","stage":3},{"id":"0107","text":"파도가 모래성을 순식간에 무너뜨렸습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0109","text":"약속 시간에 맞추려고 뛰어갔습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0112","text":"유리창에 김이 서려서 손가락으로 그림을 그렸어요.","style":"보통","lang":"Korean","stage":3},{"id":"0114","text":"예전에 살던 동네를 오랜만에 찾아갔어요.","style":"보통","lang":"Korean","stage":3},{"id":"0115","text":"와이셔츠 단추가 하나 떨어져 있었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0116","text":"워낙 바빠서 연락을 못 했어요, 미안해요.","style":"보통","lang":"Korean","stage":3},{"id":"0117","text":"위층에서 피아노 연습하는 소리가 들립니다.","style":"보통","lang":"Korean","stage":3},{"id":"0118","text":"의외로 쉬운 문제라 금방 풀었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0121","text":"우체국에 들러 소포를 부치고 왔어요.","style":"보통","lang":"Korean","stage":3},{"id":"0122","text":"이 길로 쭉 가다가 두 번째 골목에서 꺾으세요.","style":"보통","lang":"Korean","stage":3},{"id":"0123","text":"으슥한 밤길은 혼자 다니지 않는 게 좋아요.","style":"보통","lang":"Korean","stage":3},{"id":"0124","text":"아무리 바빠도 밥은 꼭 챙겨 먹어야 합니다.","style":"보통","lang":"Korean","stage":3},{"id":"0125","text":"에어컨을 켜니 방 안이 금세 시원해졌어요.","style":"보통","lang":"Korean","stage":3},{"id":"0126","text":"눈사람의 코로 당근을 꽂아 주었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0127","text":"도시락 뚜껑을 열자 김밥이 가지런히 있었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0128","text":"라디오에서 오래된 노래가 흘러나왔습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0129","text":"머리를 말리는 동안 뉴스를 들었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0130","text":"바다 건너 섬까지 배를 타고 한 시간 걸렸습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0131","text":"사과를 반으로 갈라 동생과 나눠 먹었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0132","text":"손님이 오신다고 해서 집을 청소했습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0133","text":"스웨터에 보풀이 일어서 정리했어요.","style":"보통","lang":"Korean","stage":3},{"id":"0135","text":"노을이 지는 강가에서 사진을 찍었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0136","text":"늦가을 단풍이 산을 붉게 물들였어요.","style":"보통","lang":"Korean","stage":3},{"id":"0139","text":"꽃집 앞을 지나다 프리지어 한 다발을 샀습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0140","text":"빛바랜 일기장에 어린 시절 꿈이 적혀 있었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0141","text":"굳은 결심을 하고 첫걸음을 내디뎠습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0143","text":"해님이 구름 뒤에서 살짝 얼굴을 내밀었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0144","text":"닫힌 문 너머로 웃음소리가 새어 나왔어요.","style":"보통","lang":"Korean","stage":3},{"id":"0145","text":"붙여 둔 메모지가 바람에 날아갔습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0147","text":"꽃잎 위에 이슬이 맺혀 있었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0148","text":"늦은 밤 편의점에서 컵라면을 먹었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0149","text":"흔들리는 촛불 아래서 이야기를 나눴습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0150","text":"내일은 오늘보다 조금 더 나아질 거예요.","style":"보통","lang":"Korean","stage":3},{"id":"0453","text":"품삯을 받자마자 어머니께 선물을 샀어요.","style":"보통","lang":"Korean","stage":3},{"id":"0454","text":"자기 몫의 일은 끝까지 책임지는 사람입니다.","style":"보통","lang":"Korean","stage":3},{"id":"0455","text":"걔는 원래 말수가 적은 편이에요.","style":"보통","lang":"Korean","stage":3},{"id":"0456","text":"쟤가 어제 말한 그 친구 맞지?","style":"보통","lang":"Korean","stage":3},{"id":"0457","text":"얘들아, 이제 그만 들어와서 밥 먹자.","style":"보통","lang":"Korean","stage":3},{"id":"0459","text":"손으로 먼지를 훑어 내고 상자를 열었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0461","text":"할아버지께서 옛시조 한 수를 읊으셨습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0462","text":"책장을 훑어보다가 낯익은 제목을 발견했어요.","style":"보통","lang":"Korean","stage":3},{"id":"0463","text":"시를 읊는 목소리가 교실 가득 울렸습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0465","text":"늙은 어부는 오늘도 새벽 바다로 나갑니다.","style":"보통","lang":"Korean","stage":3},{"id":"0469","text":"꿇어앉아 할머니께 새해 인사를 드렸어요.","style":"보통","lang":"Korean","stage":3},{"id":"0470","text":"끓는 물에 면을 넣고 삼 분만 기다리세요.","style":"보통","lang":"Korean","stage":3},{"id":"0475","text":"여행 마지막 날에는 일부러 지도를 보지 않고, 발길 닿는 대로 골목을 걸어 다녔어요.","style":"보통","lang":"Korean","stage":3},{"id":"0478","text":"이사 온 첫날 밤, 짐 정리를 하다 말고 바닥에 누워 새 천장을 한참 바라봤습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0479","text":"동네 꼬마들이 놀이터에 모여 누가 그네를 가장 높이 타는지 내기를 하고 있었어요.","style":"보통","lang":"Korean","stage":3},{"id":"0480","text":"할머니는 김장을 할 때마다 우리 집 몫까지 넉넉하게 챙겨 보내 주셨습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0522","text":"플레이해 주셔서 정말 감사합니다.","style":"보통","lang":"Korean","stage":3},{"id":"0523","text":"버그를 발견하시면 댓글로 알려 주세요.","style":"보통","lang":"Korean","stage":3},{"id":"0525","text":"여러분의 최고 기록을 자랑해 주세요!","style":"보통","lang":"Korean","stage":3},{"id":"0423","text":"매 판마다 지도가 바뀌어서 같은 판이 하나도 없어요.","style":"보통","lang":"Korean","stage":3},{"id":"0428","text":"몇 번을 져도 다시 도전하고 싶어지는 중독성이 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0429","text":"한 손으로도 충분히 즐길 수 있는 간단한 조작입니다.","style":"보통","lang":"Korean","stage":3},{"id":"0430","text":"친구 초대 코드를 입력하면 둘 다 선물을 받아요.","style":"보통","lang":"Korean","stage":3},{"id":"0432","text":"요리 재료를 모아 손님들이 원하는 음식을 만들어 주세요.","style":"보통","lang":"Korean","stage":3},{"id":"0433","text":"길을 막는 바위를 밀어서 출구까지 길을 만드세요.","style":"보통","lang":"Korean","stage":3},{"id":"0436","text":"두 사람이 한 화면에서 함께 즐길 수 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0438","text":"캐릭터의 얼굴, 머리, 옷까지 마음대로 꾸밀 수 있습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0439","text":"이 게임은 단 삼 분이면 한 판을 끝낼 수 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0440","text":"매주 새로운 맵이 추가되니 자주 들러 주세요.","style":"보통","lang":"Korean","stage":3},{"id":"0441","text":"누구나 쉽게, 하지만 아무나 끝까지 못 가는 게임!","style":"보통","lang":"Korean","stage":3},{"id":"0442","text":"이야기의 결말은 모두 다섯 가지가 준비되어 있습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0443","text":"몬스터를 잡으면 낮은 확률로 펫 알이 나와요.","style":"보통","lang":"Korean","stage":3},{"id":"0444","text":"정해진 시간 안에 최대한 많은 주문을 처리하세요.","style":"보통","lang":"Korean","stage":3},{"id":"0445","text":"공중에 떠 있는 섬들을 밧줄로 이어 건너가 보세요.","style":"보통","lang":"Korean","stage":3},{"id":"0446","text":"작은 마을의 우체부가 되어 편지를 배달해 주세요.","style":"보통","lang":"Korean","stage":3},{"id":"0447","text":"고양이 탐정과 함께 사라진 생선을 찾아 나섭니다.","style":"보통","lang":"Korean","stage":3},{"id":"0448","text":"눈싸움 대결에서 상대 팀을 모두 맞혀 보세요.","style":"보통","lang":"Korean","stage":3},{"id":"0449","text":"이 모든 게 메이플스토리 월드 안에서 펼쳐집니다.","style":"보통","lang":"Korean","stage":3},{"id":"0450","text":"지금 바로 시작해서 당신의 실력을 보여 주세요!","style":"보통","lang":"Korean","stage":3},{"id":"0272","text":"이번 시즌은 십이월 삼십일 일까지 이어집니다.","style":"보통","lang":"Korean","stage":3},{"id":"0274","text":"보스를 삼 분 안에 처치하면 추가 보상을 받습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0275","text":"출석 칠 일째에는 특별한 상자를 드려요.","style":"보통","lang":"Korean","stage":3},{"id":"0276","text":"하루에 다섯 번까지 무료로 도전할 수 있습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0277","text":"경험치가 이 배로 오르는 주말 이벤트가 열려요.","style":"보통","lang":"Korean","stage":3},{"id":"0278","text":"지금까지 백만 명이 넘는 모험가가 함께했습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0281","text":"첫 구매 시 다이아 천 개를 추가로 드립니다.","style":"보통","lang":"Korean","stage":3},{"id":"0283","text":"오후 여덟 시부터 열 시까지 특별 던전이 열립니다.","style":"보통","lang":"Korean","stage":3},{"id":"0285","text":"이번 업데이트로 새 지역 세 곳이 추가되었습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0286","text":"PvP 모드에서 실력을 겨뤄 보세요.","style":"보통","lang":"Korean","stage":3},{"id":"0287","text":"보스 레이드는 매주 수요일에 초기화돼요.","style":"보통","lang":"Korean","stage":3},{"id":"0290","text":"메이플스토리 월드에서 직접 만든 게임이에요.","style":"보통","lang":"Korean","stage":3},{"id":"0292","text":"HP가 바닥나기 전에 포션을 마시세요.","style":"보통","lang":"Korean","stage":3},{"id":"0295","text":"온라인 대전과 싱글 플레이를 모두 지원합니다.","style":"보통","lang":"Korean","stage":3},{"id":"0296","text":"키보드는 방향키로, 점프는 스페이스 바로 해요.","style":"보통","lang":"Korean","stage":3},{"id":"0300","text":"이 게임은 열두 살 이상 이용할 수 있습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0302","text":"골드 오천 개를 모으면 새 무기를 살 수 있습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0303","text":"이벤트 기간은 이 주 동안 진행돼요.","style":"보통","lang":"Korean","stage":3},{"id":"0307","text":"로그인 보상은 우편함에서 받을 수 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0308","text":"이 퀘스트는 삼십 레벨 이상부터 받을 수 있습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0309","text":"보스전 BGM이 정말 신나요.","style":"보통","lang":"Korean","stage":3},{"id":"0312","text":"VIP 등급이 오르면 혜택도 늘어나요.","style":"보통","lang":"Korean","stage":3},{"id":"0314","text":"몬스터 백 마리를 처치하면 칭호를 드려요.","style":"보통","lang":"Korean","stage":3},{"id":"0317","text":"와이파이가 연결된 곳에서 업데이트해 주세요.","style":"보통","lang":"Korean","stage":3},{"id":"0318","text":"서버 점검은 새벽 두 시부터 여섯 시까지입니다.","style":"보통","lang":"Korean","stage":3},{"id":"0319","text":"게임패드로도 편하게 즐길 수 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0320","text":"코인 세 개를 넣고 다시 도전하시겠어요?","style":"보통","lang":"Korean","stage":3},{"id":"0327","text":"어디로 가야 할까요?","style":"보통","lang":"Korean","stage":3},{"id":"0329","text":"이런, 길을 잃어버렸네요.","style":"보통","lang":"Korean","stage":3},{"id":"0330","text":"누구세요?","style":"보통","lang":"Korean","stage":3},{"id":"0331","text":"음, 다시 한번 생각해 볼게요.","style":"보통","lang":"Korean","stage":3},{"id":"0333","text":"괜찮아요, 다시 해 보면 돼요.","style":"보통","lang":"Korean","stage":3},{"id":"0334","text":"축하합니다, 새로운 기록이에요!","style":"보통","lang":"Korean","stage":3},{"id":"0335","text":"조심하세요!","style":"보통","lang":"Korean","stage":3},{"id":"0336","text":"이번엔 꼭 이길 수 있을까요?","style":"보통","lang":"Korean","stage":3},{"id":"0337","text":"벌써 아침이에요?","style":"보통","lang":"Korean","stage":3},{"id":"0338","text":"그럼 우리 내일 다시 만나요.","style":"보통","lang":"Korean","stage":3},{"id":"0340","text":"이쪽이에요, 따라오세요.","style":"보통","lang":"Korean","stage":3},{"id":"0341","text":"당신이라면 할 수 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0342","text":"정말 이 문을 열 건가요?","style":"보통","lang":"Korean","stage":3},{"id":"0344","text":"드디어 해냈어요!","style":"보통","lang":"Korean","stage":3},{"id":"0345","text":"아니요, 그건 제 것이 아니에요.","style":"보통","lang":"Korean","stage":3},{"id":"0346","text":"네, 알겠습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0347","text":"어때요, 마음에 드세요?","style":"보통","lang":"Korean","stage":3},{"id":"0349","text":"하하, 그거 정말 재미있네요.","style":"보통","lang":"Korean","stage":3},{"id":"0350","text":"자, 이제 시작해 볼까요?","style":"보통","lang":"Korean","stage":3},{"id":"0356","text":"이 게임의 가장 큰 재미는 친구와 함께 작전을 짜고, 서로 도우면서 어려운 보스를 쓰러뜨리는 데 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0358","text":"매일 조금씩 바뀌는 미션 덕분에, 같은 맵이라도 늘 새로운 기분으로 즐길 수 있어요.","style":"보통","lang":"Korean","stage":3},{"id":"0359","text":"해가 지면 몬스터가 더 강해지니까, 밤이 되기 전에 안전한 곳으로 돌아오는 게 좋습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0360","text":"여러분이 남겨 주신 의견을 바탕으로, 앞으로도 더 즐거운 게임을 만들어 가겠습니다.","style":"보통","lang":"Korean","stage":3},{"id":"0160","text":"내 손으로 꾸미는 나만의 작은 집!","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0161","text":"떨어지는 도토리를 바구니로 쏙쏙 받아 보세요.","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0162","text":"지금 접속하면 특별한 모자를 드려요!","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0164","text":"말랑말랑한 슬라임 친구들이 기다리고 있어요.","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0167","text":"반짝반짝 별을 모아 새로운 옷을 열어 보세요.","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0170","text":"오늘도 즐거운 하루, 같이 놀아요!","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0172","text":"새 친구를 만나고 함께 파티를 열어 보세요.","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0173","text":"보물 상자 안에는 과연 무엇이 들어 있을까요?","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0174","text":"간단한 조작으로 화려한 기술을 펼쳐 보세요!","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0178","text":"폭신폭신 구름 섬에서 낮잠도 자 보세요.","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0179","text":"최고 기록을 세우고 순위표 맨 위에 이름을 올려요!","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0485","text":"두근두근, 오늘은 어떤 선물이 나올까요?","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0488","text":"내가 만든 맵에 친구들을 초대해 보세요!","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0489","text":"아슬아슬 줄타기, 끝까지 떨어지지 마세요!","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0490","text":"모두 함께, 지금 바로 즐겨 보세요!","style":"밝고 신나게","lang":"Korean","stage":3},{"id":"0194","text":"이 섬에서는 시간이 조금 느리게 흘러요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0196","text":"눈 덮인 산장에서 따뜻한 밤을 보내 보세요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0197","text":"작은 등대가 길 잃은 배를 기다리고 있어요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0200","text":"손끝으로 그리는 선 하나가 길이 됩니다.","style":"차분하게","lang":"Korean","stage":3},{"id":"0201","text":"흩어진 빛을 모으면 새로운 길이 열려요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0203","text":"창가에 앉아 비 오는 마을을 내려다보세요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0204","text":"혼자서도, 함께여도 좋은 여행이 될 거예요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0205","text":"오늘 당신이 만든 이야기를 기다리고 있을게요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0206","text":"낡은 지도 한 장이 모든 것의 시작이었습니다.","style":"차분하게","lang":"Korean","stage":3},{"id":"0208","text":"가만히 귀 기울이면 숲이 말을 걸어와요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0209","text":"서로 다른 두 사람의 길이 하나로 이어집니다.","style":"차분하게","lang":"Korean","stage":3},{"id":"0210","text":"지금, 당신만의 속도로 시작해 보세요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0491","text":"오래된 서점의 문을 열면, 잊고 있던 이야기가 기다립니다.","style":"차분하게","lang":"Korean","stage":3},{"id":"0497","text":"오늘 하루, 수고 많으셨어요.","style":"차분하게","lang":"Korean","stage":3},{"id":"0500","text":"이제 마지막 페이지를 넘길 시간입니다.","style":"차분하게","lang":"Korean","stage":3},{"id":"0224","text":"버티세요, 조금만 더 버티면 됩니다.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0226","text":"지금 들린 소리, 분명 바람 소리는 아니었어요.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0227","text":"함정은 언제나 가장 안전해 보이는 곳에 있습니다.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0229","text":"제한 시간 안에 모든 불을 꺼야 합니다.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0232","text":"손을 떼는 순간, 모든 것이 무너집니다.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0234","text":"보스의 분노 게이지가 가득 찼습니다.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0239","text":"빛이 사라지기 전에 출구를 찾아야 합니다.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0240","text":"당신은 이 밤을 무사히 넘길 수 있을까요?","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0503","text":"경보가 울리기까지 남은 시간은 삼십 초.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0504","text":"천장에서 무언가가 기어 다니는 소리가 납니다.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0506","text":"열면 안 되는 문이 있다면, 바로 이 문입니다.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0507","text":"숨소리조차 들리지 않게, 아주 조용히.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0508","text":"다리가 끊어지기 전에 건너편으로 뛰세요!","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0509","text":"지금 당신 뒤에 서 있는 건 누구일까요?","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0510","text":"마지막 기회입니다, 놓치지 마세요.","style":"긴장감 있게","lang":"Korean","stage":3},{"id":"0254","text":"잊혀진 왕관의 주인이 마침내 돌아왔다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0257","text":"모든 길은 하나의 성으로 이어진다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0258","text":"어둠을 몰아낼 빛, 그것은 바로 당신입니다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0259","text":"영원할 것 같던 평화가 깨지던 날.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0260","text":"고대의 문이 열리고, 시험이 시작됩니다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0263","text":"전설은 기록되지 않는다, 오직 살아남을 뿐.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0266","text":"거인의 발걸음에 대지가 울립니다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0269","text":"역사는 승자의 이름을 기억할 것이다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0270","text":"이제, 당신의 전설을 써 내려갈 시간입니다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0511","text":"잠들었던 화산이 깨어나고, 대지가 불타오른다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0512","text":"수많은 별 가운데, 단 하나의 별이 길을 밝힌다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0515","text":"모든 전설에는 시작이 있다, 그리고 지금이 그 순간이다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0518","text":"잊혀진 신전의 종소리가 다시 울려 퍼진다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0519","text":"그대의 이름이 영원히 노래될 것이다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0520","text":"지금, 세계의 운명을 건 여정이 시작됩니다.","style":"웅장하게","lang":"Korean","stage":3},{"id":"0411","text":"Press the space bar to jump and the arrow keys to move.","style":"보통","lang":"English","stage":3},{"id":"0412","text":"Up to four players can join the same party.","style":"보통","lang":"English","stage":3},{"id":"0413","text":"The event runs until the thirty-first of December.","style":"보통","lang":"English","stage":3},{"id":"0414","text":"Defeat the boss in under three minutes for a bonus reward.","style":"보통","lang":"English","stage":3},{"id":"0415","text":"Your survival time is recorded on the leaderboard.","style":"보통","lang":"English","stage":3},{"id":"0416","text":"Thank you for playing, see you next time!","style":"보통","lang":"English","stage":3},{"id":"0417","text":"Is this really the end?","style":"보통","lang":"English","stage":3},{"id":"0418","text":"Wow, that was amazing!","style":"보통","lang":"English","stage":3},{"id":"0419","text":"Wait, did you hear that?","style":"보통","lang":"English","stage":3},{"id":"0420","text":"Great job, you set a new record!","style":"보통","lang":"English","stage":3},{"id":"0526","text":"This is my very first game, I hope you enjoy it.","style":"보통","lang":"English","stage":3},{"id":"0527","text":"Thank you so much for playing!","style":"보통","lang":"English","stage":3},{"id":"0528","text":"If you find a bug, please let me know in the comments.","style":"보통","lang":"English","stage":3},{"id":"0529","text":"A co-op mode is coming in the next update.","style":"보통","lang":"English","stage":3},{"id":"0530","text":"Share your best score with your friends!","style":"보통","lang":"English","stage":3},{"id":"0535","text":"Choose your character and start your journey.","style":"보통","lang":"English","stage":3},{"id":"0536","text":"Watch out for traps hidden under the leaves.","style":"보통","lang":"English","stage":3},{"id":"0537","text":"The faster you finish, the higher your score.","style":"보통","lang":"English","stage":3},{"id":"0538","text":"Unlock new outfits by collecting shining stars.","style":"보통","lang":"English","stage":3},{"id":"0539","text":"Invite your friends with a single click.","style":"보통","lang":"English","stage":3},{"id":"0540","text":"See you in the next adventure!","style":"보통","lang":"English","stage":3},{"id":"0531","text":"Ding dong, a new friend just arrived in town!","style":"밝고 신나게","lang":"English","stage":3},{"id":"0386","text":"The old lighthouse is still waiting for the last ship.","style":"차분하게","lang":"English","stage":3},{"id":"0387","text":"Listen closely, and the wind will show you the way.","style":"차분하게","lang":"English","stage":3},{"id":"0388","text":"Every small step brings you closer to home.","style":"차분하게","lang":"English","stage":3},{"id":"0389","text":"Watch the rain fall over the sleepy little town.","style":"차분하게","lang":"English","stage":3},{"id":"0390","text":"Begin your journey at your own pace.","style":"차분하게","lang":"English","stage":3},{"id":"0532","text":"Plant a seed today and wait for tomorrow.","style":"차분하게","lang":"English","stage":3},{"id":"0391","text":"Don't touch it, the balloon could burst at any moment.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0392","text":"Something is watching you from the dark.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0393","text":"Ten seconds left, make your choice now.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0394","text":"Hold your breath, it's right behind the door.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0395","text":"The floor is collapsing, run!","style":"긴장감 있게","lang":"English","stage":3},{"id":"0396","text":"Only one of you will make it out alive.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0397","text":"One wrong move, and it's all over.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0398","text":"Find the exit before the lights go out.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0399","text":"Someone here is lying, and you have to find out who.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0400","text":"Can you make it through the night?","style":"긴장감 있게","lang":"English","stage":3},{"id":"0533","text":"Don't move, it's looking right at you.","style":"긴장감 있게","lang":"English","stage":3},{"id":"0401","text":"An ancient legend awakens once again.","style":"웅장하게","lang":"English","stage":3},{"id":"0402","text":"The fate of the kingdom rests in your hands.","style":"웅장하게","lang":"English","stage":3},{"id":"0403","text":"Raise your sword, the final battle begins.","style":"웅장하게","lang":"English","stage":3},{"id":"0404","text":"Scattered heroes rise and stand as one.","style":"웅장하게","lang":"English","stage":3},{"id":"0405","text":"Beyond the endless desert lies a city of gold.","style":"웅장하게","lang":"English","stage":3},{"id":"0406","text":"A new age dawns with the roar of thunder.","style":"웅장하게","lang":"English","stage":3},{"id":"0407","text":"Twelve towers, twelve lords, and only one throne.","style":"웅장하게","lang":"English","stage":3},{"id":"0408","text":"History will remember the name of the brave.","style":"웅장하게","lang":"English","stage":3},{"id":"0409","text":"The last hope of this world opens its eyes.","style":"웅장하게","lang":"English","stage":3},{"id":"0410","text":"Now it's time to write your own legend.","style":"웅장하게","lang":"English","stage":3},{"id":"0534","text":"Every legend has a beginning, and this is the moment.","style":"웅장하게","lang":"English","stage":3}]};
